// og:video previews for the landing and product pages, so X, LinkedIn, Slack, and others autoplay a short
// product loop instead of a still card. Files are generated by `bun run generate:social-videos`.
export const ogVideoWidth = 1280
export const ogVideoHeight = 672

export type OgVideo = {
  /** Video id in scripts/generate-social-videos.ts. */
  slug: string
  url: string
}

const video = (slug: string): OgVideo => ({ slug, url: `/social/videos/capgo-${slug}.mp4` })

/** Keyed by the page path without its locale prefix, so every translation shares the same video. */
export const ogVideos: Record<string, OgVideo> = {
  '/': video('home'),
  '/live-update/': video('live-update'),
  '/observe/': video('observe'),
  '/native-build/': video('native-build'),
  '/notifications/': video('notifications'),
  '/capgo-cli/': video('cli'),
  '/app_mobile/': video('app-mobile'),
  '/plugins/': video('plugins'),
  '/ionic-enterprise-plugins/': video('ionic-plugins'),
  '/skills/': video('skills'),
  '/agents/': video('agents'),
}
